def gap(x):
    return (x * x - 9) / (x - 3)

assert abs(gap(3.0001) - 6) < 1e-3
assert abs(gap(2.9999) - 6) < 1e-3

def repaired_limit(x):
    return (x * x - 4) / (x - 2)

assert abs(repaired_limit(2.0001) - 4) < 1e-3

def cubic(t):
    return t ** 3 + t - 1

assert cubic(0) < 0 < cubic(1)
assert cubic(0.5) < 0
